parameters.jsCode:
// Read Gemini response
const rawText =
  $json.candidates?.[0]?.content?.parts?.[0]?.text || "";

// Parse Gemini JSON
let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    mood: "unknown",
    response: "I'm here with you",
    story: "",
    playlist: ""
  };
}

// Build final Telegram message
let finalMessage = `Hey\nMood: ${parsed.mood}\n\n${parsed.response}`;

if (parsed.story) {
  finalMessage += `\n\nStory:\n${parsed.story}`;
}

if (parsed.playlist) {
  finalMessage += `\n\nWatch here:\n${parsed.playlist}`;
}

return [
  {
    json: {
      text: finalMessage
    }
  }
];
